import { formatDate } from "../utils/formatDate";
export const getLabel = (value, dateFormat, timeFormat, translate, toLocalDateTime, timeSelect, buttonLabel, buttonTitle) => {
    if (!value) {
        return buttonLabel ? buttonLabel : translate("Pick a date");
    }
    const format = timeSelect ? `${dateFormat} ${timeFormat}` : dateFormat;
    return buttonTitle ? `${translate("Date filter:")} ${formatDate(toLocalDateTime(value), format, translate)}` : formatDate(toLocalDateTime(value), format, translate);
};
